def find_largest_expression(A, B):
    expressions = [A + B, A - B, A * B]
    return max(expressions)

if __name__ == "__main__":
    import sys
    input = sys.stdin.read
    data = input().strip()
    A, B = map(int, data.split())
    result = find_largest_expression(A, B)
    print(result)
